class A {
    int a; private int b; protected int c;
    A(int aa, int bb, int cc) { a=aa; b=bb; c=cc; }
    int hap() { return a+b+c; }
}
class B extends A {
    B(int aa, int bb, int cc) { super(aa,bb,cc); }
    @Override public int hap() { return a*c; }
}
public class Main {
    public static void main(String[] args) {
        A aaa=new A(1,5,3); B bbb=new B(10,30,50);
        System.out.print(aaa.hap()+bbb.hap());
    }
}
